#!/usr/bin/env sh
# fetch Yamanashi~Nanbutown~Nanbucyoueibasu (JP) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://api.gtfs-data.jp/v2/organizations/yamanashi-nanbutown/feeds/nanbucyoueibasu/files/feed.zip?uid=39fd9f34-ce71-4aba-a53c-8895a5d5e277"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
